import type { Theme } from "@types";
import type { EmotionCache } from "@emotion/react";

import { CacheProvider, ClassNames, css, Global, ThemeProvider } from "@emotion/react";
import React, { useEffect, useMemo, useState } from "react";
import { DirectionProvider } from "@radix-ui/react-direction";

import defaultTheme from "../bundled-themes/default";
import { createTexturaCache } from "../utils/create-emotion-cache";

const useHydrated = () => {
  const [hydrated, setHydrated] = useState(false);
  useEffect(() => {
    const timeoutId = setTimeout(() => {
      setHydrated(true);
    }, 0);
    return () => clearTimeout(timeoutId);
  }, []);
  return hydrated;
};

export interface ThemeProviderProps {
  applyThemeScopedStyles?: boolean;
  as?: React.ElementType;
  children?: React.ReactNode;
  dir?: "ltr" | "rtl";
  emotionCache?: EmotionCache;
  hoistCSSVars?: boolean;
  hoistThemeScopedStyles?: boolean;
  theme?: Theme;
}

const TexturaThemeProvider = ({
  applyThemeScopedStyles = true,
  as: Component,
  dir: propDir,
  emotionCache: propCache,
  theme = defaultTheme,
  children,
  hoistCSSVars = false,
  hoistThemeScopedStyles = false,
}: ThemeProviderProps) => {
  const themeScopedStyles = useMemo(() => theme.themeScopedStyles, [theme]),
    isThemeScopedStylesString = typeof themeScopedStyles === "string",
    cssVars = theme.cssVariables;

  const hydrated = useHydrated();
  const effectiveDir = useMemo(() => {
    if (propDir) {
      return propDir;
    }
    if (hydrated && typeof window !== "undefined") {
      const documentDir = document?.documentElement.dir;
      if (documentDir === "ltr" || documentDir === "rtl") {
        return documentDir;
      }
    }
    return "ltr";
  }, [propDir, hydrated]);
  const emotionCache = useMemo(() => propCache || createTexturaCache(), [propCache]);
  Component = !Component ? "div" : Component;
  return (
    <DirectionProvider dir={effectiveDir}>
      <CacheProvider value={emotionCache}>
        <ThemeProvider theme={theme}>
          {hoistThemeScopedStyles && themeScopedStyles && applyThemeScopedStyles && (
            <Global
              styles={
                isThemeScopedStylesString
                  ? css`
                      ${themeScopedStyles}
                    `
                  : css({
                      ":root": { ...themeScopedStyles },
                    })
              }
            />
          )}
          {hoistCSSVars && cssVars && (
            <Global
              styles={css`
                :root {
                  ${cssVars}
                }
              `}
            />
          )}
          <ClassNames>
            {({ css: inlineCss, cx }) => {
              const cssVarsCss = inlineCss`
            ${cssVars}
          `;
              const themeScopedStylesCss = isThemeScopedStylesString
                ? inlineCss`
              ${themeScopedStyles}
            `
                : inlineCss({ ...themeScopedStyles });

              if (Component === React.Fragment) {
                return <Component>{children}</Component>;
              }
              return (
                <Component
                  className={cx(cssVarsCss, applyThemeScopedStyles && themeScopedStylesCss)}
                  data-textura-theme-provider="true"
                  dir={effectiveDir}
                >
                  {children}
                </Component>
              );
            }}
          </ClassNames>
        </ThemeProvider>
      </CacheProvider>
    </DirectionProvider>
  );
};

TexturaThemeProvider.displayName = "ThemeProvider";

export default TexturaThemeProvider;
